 const c=this.buffer.getContext('2d'),horizon=h*(.48+this.lookY)+p.jump*35,scale=w*.64;c.imageSmoothingEnabled=false;c.fillStyle='#0b121c';c.fillRect(0,0,w,h);c.fillStyle='#202830';c.fillRect(0,horizon,w,h);for(let y=Math.max(0,horizon);y<h;y+=16){c.fillStyle=y%32<16?'#252e35':'#202830';c.fillRect(0,y,w,1);}const depth=[];
