 const objects=[{...this.exit,kind:'exit'},{...this.computer,kind:'computer'},...this.game.enemies.filter(e=>e.phase==='inside').map(e=>({...this.enemyPosition(e),kind:'enemy',enemy:e})),...this.bullets.map(b=>({...b,kind:'bullet'})),...this.game.mines.filter(m=>m.fps).map(m=>({...m.fps,kind:'mine'})),...this.game.bonuses.filter(b=>b.fps).map(b=>({...b.fps,kind:'bonus'}))];objects.sort((a,b)=>Math.hypot(b.x-p.x,b.z-p.z)-Math.hypot(a.x-p.x,a.z-p.z));
